      events:{
        VARIABLE_UPDATE_STARTED:"VARIABLE_UPDATE_STARTED",
        VARIABLE_UPDATE_ENDED:"VARIABLE_UPDATE_ENDED",
        VARIABLE_UPDATE_FAILED:"VARIABLE_UPDATE_FAILED"
      },
      state:{}
